1	package relayproof
2	
3	// Regression coverage for the read/write priority boundary where the read
4	// fault and its bytes arrive in the SAME underlying Read call. A buffering
5	// reader latches an error delivered together with a delimiter-ended chunk:
6	// the complete line is handed up with a nil error and the fault surfaces only
7	// on the next line read, so an output fault fired while emitting the
8	// just-completed line's result previously masked the already-delivered read
9	// cause and callers mistook an interrupted input for a write-only failure.
10	//
11	// The fixed contract asserted here:
12	//   - a non-EOF read fault delivered with complete newline-ended logs stays
13	//     the primary failure even when the output fails while emitting those very
14	//     results, whether the failing write is the long result itself or only the
15	//     flush of earlier buffered results it forces; errors.Is must match
16	//     ErrLogRead and the reader's original cause, and must NOT match
17	//     ErrLogWrite or the write cause, while both causes still show in the text;
18	//   - processing stops without another Read; accepted bytes stay the normal
19	//     prefix (a final JSON may be cut open), no log-failure record is
20	//     fabricated, legal logs never become illegal, and neither unprocessed
21	//     lines nor the fault's newline-less tail count — so failures may be zero
22	//     while the read interruption is still returned;
23	//   - the same rules hold under the source-CIDR filter with its physical line
24	//     numbers and per-line error content.
25	//
26	// Everything is scripted in-process with failWriter from normalize_io_test.go,
27	// so the boundary reproduces deterministically offline.
28	
29	import (
30		"bytes"
31		"errors"
32		"strings"
33		"testing"
34	)
35	
36	// faultWithBatchReader serves data, copying no more than the caller's buffer,
37	// and returns faultErr on the Read whose copied bytes reach faultAt (the
38	// newline that completes the last whole log in the batch); every later Read
39	// returns the same persistent fault with no more bytes. This models a device
40	// that delivers a final batch and stays broken. Unlike scriptReader it never
41	// panics on a small caller buffer, so it reproduces the error-latching boundary
42	// against a buffering reader of any internal size.
43	type faultWithBatchReader struct {
44		data           []byte
45		faultAt        int
46		faultErr       error
47		pos            int
48		faulted        bool
49		reads          int
50		postFaultReads int // Read calls after the fault-delivering batch
51	}
52	
53	func (r *faultWithBatchReader) Read(p []byte) (int, error) {
54		r.reads++
55		if r.faulted {
56			r.postFaultReads++
57			return 0, r.faultErr
58		}
59		n := copy(p, r.data[r.pos:])
60		end := r.pos + n
61		r.pos = end
62		if end > r.faultAt { // the batch's terminating newline went out with these bytes
63			r.faulted = true
64			return n, r.faultErr
65		}
66		return n, nil
67	}
68	
69	// newFaultWithBatchReader builds a stream of prefix + lastCompleteLine + "\n" +
70	// tail, where the Read that delivers lastCompleteLine's newline also delivers
71	// the fault; the newline-less tail rides along inside that same batch.
72	func newFaultWithBatchReader(prefix, lastCompleteLine, tail string) *faultWithBatchReader {
73		data := prefix + lastCompleteLine + "\n" + tail
74		return &faultWithBatchReader{
75			data:     []byte(data),
76			faultAt:  len(prefix) + len(lastCompleteLine), // index of the '\n'
77			faultErr: errSimulatedRead,
78		}
79	}
80	
81	// expectReadPrimaryOverWrite is the shared error-classification contract for a
82	// read fault that is already in hand when an output fault fires.
83	func expectReadPrimaryOverWrite(t *testing.T, err error) {
84		t.Helper()
85		if err == nil {
86			t.Fatalf("a read fault must be returned even with a later write fault, got nil")
87		}
88		if !errors.Is(err, ErrLogRead) {
89			t.Fatalf("error must classify as the read failure, got %v", err)
90		}
91		if !errors.Is(err, errSimulatedRead) {
92			t.Fatalf("the reader's original cause must stay reachable, got %v", err)
93		}
94		if errors.Is(err, ErrLogWrite) {
95			t.Fatalf("the later write fault must not tag the error as a write failure: %v", err)
96		}
97		if errors.Is(err, errSimulatedWrite) {
98			t.Fatalf("the later write cause must not join the error chain: %v", err)
99		}
100		msg := err.Error()
101		if !strings.Contains(msg, errSimulatedRead.Error()) {
102			t.Fatalf("message must name the read cause, got %q", msg)
103		}
104		if !strings.Contains(msg, errSimulatedWrite.Error()) {
105			t.Fatalf("the write fault must stay visible in the message text, got %q", msg)
106		}
107	}
108	
109	// A small invalid complete log is buffered, then a long valid complete log and
110	// a newline-less tail arrive with the read fault. Emitting the long log forces
111	// a physical write (of the buffered failure result, then of the long result)
112	// that fails: the read cause must still win, with only the invalid line
113	// counted and the accepted bytes kept as a normal-output prefix.
114	func TestNormalizeIOReadFaultWithBytesWinsOverMidStreamWriteFault(t *testing.T) {
115		invalid := `{"timestamp":"not-a-time","action":"bad"}`
116		big := bigValidLog("big")
117		if len(encodedRecord(t, 2, big)) <= 4096 {
118			t.Fatalf("test setup: encoded long line must exceed the 4096-byte write buffer")
119		}
120		prefix := invalid + "\n"
121		complete := prefix + big + "\n"
122		fragment := `{"timestamp":"2026-01-02T00:00:00Z","action":"fault-tail"}`
123	
124		var healthy bytes.Buffer
125		healthyFailures, healthyErr := NormalizeReader(strings.NewReader(complete), &healthy)
126		if healthyErr != nil || healthyFailures != 1 {
127			t.Fatalf("test setup: healthy reference read failed: failures=%d err=%v", healthyFailures, healthyErr)
128		}
129		firstRecord := encodedRecord(t, 1, invalid)
130	
131		cases := []struct {
132			name       string
133			allowBytes int // bytes the writer accepts before the failing write
134			partial    int // bytes accepted by the failing write itself
135			wantKept   int // total bytes that must remain
136			whole      int // whole records the kept prefix must decode to
137		}{
138			{
139				// The flush of the already-buffered failure result is the first
140				// physical write and fails immediately: nothing is kept.
141				name:       "flush of prior buffered result fails first",
142				allowBytes: 0,
143				partial:    0,
144				wantKept:   0,
145				whole:      0,
146			},
147			{
148				// The buffered failure result flushes whole; the direct write of
149				// the long result accepts 120 bytes and then fails.
150				name:       "long result write fails after the buffered result",
151				allowBytes: len(firstRecord),
152				partial:    120,
153				wantKept:   len(firstRecord) + 120,
154				whole:      1,
155			},
156		}
157		for _, tc := range cases {
158			t.Run(tc.name, func(t *testing.T) {
159				src := newFaultWithBatchReader(prefix, big, fragment)
160				w := &failWriter{allowBytes: tc.allowBytes, partial: tc.partial, err: errSimulatedWrite}
161				failures, err := NormalizeReader(src, w)
162				expectReadPrimaryOverWrite(t, err)
163				if failures != 1 {
164					t.Fatalf("only the invalid complete line counts; the legal long line and fault tail add nothing, got %d", failures)
165				}
166				if src.postFaultReads != 0 {
167					t.Fatalf("processing must stop on the write fault without another Read, got %d post-fault reads", src.postFaultReads)
168				}
169				if w.buf.Len() != tc.wantKept {
170					t.Fatalf("accepted bytes must total %d, got %d", tc.wantKept, w.buf.Len())
171				}
