package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"

	"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
)

var errDeviceLost = errors.New("upstream device lost")

// oneShotReader delivers all of data together with err on the first Read.
type oneShotReader struct {
	data      []byte
	err       error
	delivered bool
}

func (r *oneShotReader) Read(p []byte) (int, error) {
	if r.delivered {
		return 0, io.EOF
	}
	r.delivered = true
	n := copy(p, r.data)
	if n < len(r.data) {
		panic("data larger than buffer")
	}
	return n, r.err
}

// same batch for every scenario:
//
//	line 1: valid log, newline-ended
//	line 2: invalid timestamp, newline-ended
//	line 3: valid log WITHOUT a trailing newline
var batch = "" +
	`{"timestamp":"2026-01-02T00:00:00Z","action":"ok-1"}` + "\n" +
	`{"timestamp":"not-a-time","action":"bad-2"}` + "\n" +
	`{"timestamp":"2026-01-02T00:00:00Z","action":"tail-3"}`

func run(name string, src io.Reader) {
	var out bytes.Buffer
	failures, err := relayproof.NormalizeReader(src, &out)
	fmt.Printf("=== %s ===\n", name)
	fmt.Printf("output:\n%s", out.String())
	fmt.Printf("failures=%d err=%v\n", failures, err)
	fmt.Printf("errors.Is ErrLogRead=%v errors.Is deviceErr=%v errors.Is ErrLogWrite=%v\n\n",
		errors.Is(err, relayproof.ErrLogRead),
		errors.Is(err, errDeviceLost),
		errors.Is(err, relayproof.ErrLogWrite))
}

func main() {
	run("A: plain io.EOF (normal end)", &oneShotReader{data: []byte(batch), err: io.EOF})
	run("B: wrapped join(io.EOF, deviceErr) (interruption)",
		&oneShotReader{
			data: []byte(batch),
			err:  fmt.Errorf("upstream closed mid-batch: %w", errors.Join(io.EOF, errDeviceLost)),
		})
	run("C: only the newline-less fragment + combined error (interruption)",
		&oneShotReader{
			data: []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"tail-3"}`),
			err:  errors.Join(io.EOF, errDeviceLost),
		})
}

