package main

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"

	"github.com/asdhoaiqqq/relayproof-bridge/relayproof"
)

var (
	errDeviceLost = errors.New("upstream device lost")
	errSinkBroken = errors.New("downstream sink broken")
)

// oneShotReader delivers all of data together with err on the first Read.
type oneShotReader struct {
	data      []byte
	err       error
	delivered bool
}

func (r *oneShotReader) Read(p []byte) (int, error) {
	if r.delivered {
		return 0, io.EOF
	}
	r.delivered = true
	return copy(p, r.data), r.err
}

// failingWriter accepts allowBytes in total, then fails (accepting up to
// partial more bytes on the failing call itself).
type failingWriter struct {
	buf        bytes.Buffer
	allowBytes int
	partial    int
}

func (w *failingWriter) Write(p []byte) (int, error) {
	accepted := 0
	if w.allowBytes > 0 {
		n := min(len(p), w.allowBytes)
		w.buf.Write(p[:n])
		w.allowBytes -= n
		accepted, p = n, p[n:]
		if len(p) == 0 {
			return accepted, nil
		}
	}
	m := min(w.partial, len(p))
	w.buf.Write(p[:m])
	return accepted + m, errSinkBroken
}

// Same batch for every scenario:
//
//	line 1: valid log, newline-ended
//	line 2: invalid timestamp, newline-ended
//	line 3: valid log WITHOUT a trailing newline
const batch = "" +
	`{"timestamp":"2026-01-02T00:00:00Z","action":"ok-1"}` + "\n" +
	`{"timestamp":"not-a-time","action":"bad-2"}` + "\n" +
	`{"timestamp":"2026-01-02T00:00:00Z","action":"tail-3"}`

func report(name string, failures int, err error, out []byte) {
	fmt.Printf("=== %s ===\n", name)
	fmt.Printf("output:\n%s", out)
	fmt.Printf("failures=%d\nerr=%v\n", failures, err)
	fmt.Printf("Is(ErrLogRead)=%v Is(deviceErr)=%v Is(ErrLogWrite)=%v Is(sinkErr)=%v\n\n",
		errors.Is(err, relayproof.ErrLogRead),
		errors.Is(err, errDeviceLost),
		errors.Is(err, relayproof.ErrLogWrite),
		errors.Is(err, errSinkBroken))
}

func main() {
	// A: plain io.EOF — normal completion, last line without newline processed.
	var out bytes.Buffer
	f, e := relayproof.NormalizeReader(&oneShotReader{data: []byte(batch), err: io.EOF}, &out)
	report("A plain io.EOF", f, e, out.Bytes())

	// B: wrapped join(io.EOF, deviceErr) — read interruption.
	out.Reset()
	f, e = relayproof.NormalizeReader(&oneShotReader{
		data: []byte(batch),
		err:  fmt.Errorf("upstream closed mid-batch: %w", errors.Join(io.EOF, errDeviceLost)),
	}, &out)
	report("B wrapped EOF+fault", f, e, out.Bytes())

	// C: only the newline-less fragment rides the combined error.
	out.Reset()
	f, e = relayproof.NormalizeReader(&oneShotReader{
		data: []byte(`{"timestamp":"2026-01-02T00:00:00Z","action":"tail-3"}`),
		err:  errors.Join(io.EOF, errDeviceLost),
	}, &out)
	report("C fragment only", f, e, out.Bytes())

	// D: read fault already in hand; shutdown flush of buffered results fails.
	fw := &failingWriter{}
	f, e = relayproof.NormalizeReader(
		&oneShotReader{data: []byte(batch), err: errors.Join(io.EOF, errDeviceLost)}, fw)
	report("D read fault then flush fault", f, e, fw.buf.Bytes())

	// E: healthy input, writer fails on the final flush.
	fw = &failingWriter{}
	f, e = relayproof.NormalizeReader(strings.NewReader(batch), fw)
	report("E healthy read, flush fault", f, e, fw.buf.Bytes())
}

